"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[643],{6643:function(e,t,i){i.r(t),i.d(t,{BlogProvider:function(){return BlogProvider},useBlog:function(){return useBlog}});var a=i(7437),n=i(2265);let r=(0,n.createContext)(void 0),o="stews-blog-posts",s=[{id:1,title:"My First Week in Tbilisi",excerpt:"Just arrived in Georgia's capital and I'm already falling in love with this incredible city. Here are my first impressions...",content:"<h2>Arriving in Georgia's Capital</h2>\n<p>After months of planning and anticipation, I've finally made it to Tbilisi! The journey here was long but worth every minute. As I stepped off the plane at Shota Rustaveli Tbilisi International Airport, I could feel the excitement building.</p>\n\n<h3>First Impressions</h3>\n<p>Walking through the streets of Old Town for the first time was absolutely magical. The cobblestone streets, the mix of ancient and modern architecture, and the incredible hospitality of the Georgian people immediately made me feel welcome.</p>\n\n<h3>The Food Scene</h3>\n<p>I've already tried khachapuri (the cheese-filled bread that Georgia is famous for) and khinkali (traditional soup dumplings). Every meal has been an adventure, and I'm excited to explore more of the incredible Georgian cuisine.</p>\n\n<h3>Language Challenges</h3>\n<p>Georgian script looks like beautiful art, but it's definitely challenging to learn! I've managed to master \"gamarjoba\" (hello) and \"madloba\" (thank you), which has earned me smiles from locals.</p>\n\n<h3>What's Next</h3>\n<p>I'm planning to explore more neighborhoods, find a good coffee shop to work from, and maybe take some Georgian language lessons. This is just the beginning of what I know will be an incredible journey.</p>",author:"Stew Norriss",date:"2024-10-20",readTime:"5 min read",category:"Personal",published:!0,hasImages:!0,hasVideo:!1,featuredImage:"https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=800&h=400&fit=crop&crop=center",tags:["tbilisi","first-impressions","georgia","expat-life"],createdAt:"2024-10-20T10:00:00Z",updatedAt:"2024-10-20T10:00:00Z"},{id:2,title:"Best Coffee Shops I've Discovered",excerpt:"As a coffee enthusiast, I've been exploring Tbilisi's amazing cafe scene. Here are my top picks so far...",content:"<h2>A Coffee Lover's Guide to Tbilisi</h2>\n<p>As someone who can't function without good coffee, finding the best cafes in Tbilisi has been a top priority. After extensive \"research\" (aka drinking lots of coffee), here are my favorites so far.</p>\n\n<h3>Stamba Cafe</h3>\n<p>Located in the trendy Stamba Hotel, this cafe serves some of the best specialty coffee in the city. The industrial-chic atmosphere and perfectly crafted lattes make it my go-to spot for morning work sessions.</p>\n\n<h3>Cafe Leila</h3>\n<p>A cozy neighborhood gem with amazing Georgian coffee and homemade pastries. The owner, Leila, always greets me with a smile and is helping me practice my Georgian!</p>\n\n<h3>Prospero's Books & Caliban's Coffee</h3>\n<p>A bookstore-cafe combo that's perfect for rainy afternoons. Great coffee, English books, and a quiet atmosphere for reading or writing. Plus, they have the best carrot cake in town.</p>\n\n<h3>The Hunt Continues</h3>\n<p>I'm still exploring and discovering new spots every week. If you have recommendations, let me know! The coffee culture here is thriving, and I'm excited to try every single cafe in the city.</p>",author:"Stew Norriss",date:"2024-10-18",readTime:"7 min read",category:"Food & Drink",published:!0,hasImages:!0,hasVideo:!1,featuredImage:"https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?w=800&h=400&fit=crop&crop=center",tags:["coffee","cafes","tbilisi","food-drink"],createdAt:"2024-10-18T09:00:00Z",updatedAt:"2024-10-18T09:00:00Z"},{id:3,title:"Learning Georgian: My Journey So Far",excerpt:"Tackling one of the world's most unique languages. Here's what I've learned about learning Georgian...",content:"<h2>Tackling One of the World's Most Unique Languages</h2>\n<p>Georgian is unlike any language I've ever encountered. With its own unique script and complex grammar, it's been both challenging and fascinating to learn.</p>\n\n<h3>The Georgian Alphabet</h3>\n<p>The Georgian script (called Mkhedruli) has 33 letters and looks absolutely beautiful. Each letter is like a small work of art. I've been practicing writing them every day, and slowly but surely, I'm getting the hang of it.</p>\n\n<h3>Basic Phrases I've Mastered</h3>\n<ul>\n<li><strong>Gamarjoba</strong> (გამარჯობა) - Hello</li>\n<li><strong>Madloba</strong> (მადლობა) - Thank you</li>\n<li><strong>Bodishi</strong> (ბოდიში) - Sorry/Excuse me</li>\n<li><strong>Nakhvamdis</strong> (ნახვამდის) - Goodbye</li>\n</ul>\n\n<h3>The Challenges</h3>\n<p>Georgian grammar is incredibly complex, with cases, verb conjugations, and sentence structures that are completely different from English. But every small victory feels amazing!</p>\n\n<h3>My Learning Strategy</h3>\n<p>I'm using a combination of language apps, local tutors, and most importantly, trying to practice with locals whenever possible. Georgians are incredibly patient and encouraging when they see foreigners trying to learn their language.</p>",author:"Stew Norriss",date:"2024-10-15",readTime:"6 min read",category:"Language",published:!0,hasImages:!1,hasVideo:!0,featuredImage:"https://images.unsplash.com/photo-1481627834876-b7833e8f5570?w=800&h=400&fit=crop&crop=center",tags:["georgian-language","learning","alphabet","culture"],createdAt:"2024-10-15T14:00:00Z",updatedAt:"2024-10-15T14:00:00Z"},{id:4,title:"Exploring Old Town Tbilisi",excerpt:"A photo and video journey through the historic heart of the city. The architecture here is absolutely stunning...",content:"<h2>A Journey Through Time</h2>\n<p>Old Town Tbilisi is like stepping into a living museum. Every corner tells a story, every building has character, and the blend of architectural styles creates a unique atmosphere you won't find anywhere else in the world.</p>\n\n<h3>The Sulfur Baths</h3>\n<p>The famous sulfur baths that gave Tbilisi its name are still operating today. The distinctive domed structures are iconic, and taking a bath in the natural hot springs is an experience every visitor should have.</p>\n\n<h3>Narikala Fortress</h3>\n<p>Perched high above the city, this ancient fortress offers breathtaking views of Tbilisi. The climb up is worth it, especially at sunset when the whole city is bathed in golden light.</p>\n\n<h3>The Architecture</h3>\n<p>What fascinates me most is how different architectural periods coexist harmoniously. You'll see medieval churches next to Art Nouveau buildings, Soviet-era structures alongside modern glass towers.</p>\n\n<h3>Hidden Gems</h3>\n<p>Every day I discover new courtyards, small galleries, and charming cafes tucked away in the narrow streets. Old Town rewards those who take time to wander and explore.</p>",author:"Stew Norriss",date:"2024-10-12",readTime:"4 min read",category:"Travel",published:!0,hasImages:!0,hasVideo:!0,featuredImage:"https://images.unsplash.com/photo-1565552645632-d725f8bfc19a?w=800&h=400&fit=crop&crop=center",tags:["old-town","architecture","photography","travel"],createdAt:"2024-10-12T16:00:00Z",updatedAt:"2024-10-12T16:00:00Z"},{id:5,title:"Finding an Apartment in Tbilisi: A Guide for Expats",excerpt:"The ins and outs of apartment hunting in Georgia's capital. What I wish I knew before I started looking...",content:"<h2>Navigating Tbilisi's Rental Market</h2>\n<p>Finding the right apartment in Tbilisi can be challenging, but with the right approach and knowledge, you can find a great place to call home. Here's what I learned during my apartment hunt.</p>\n\n<h3>Popular Neighborhoods for Expats</h3>\n<p><strong>Vake:</strong> Upscale area with modern amenities, great for families and professionals. Expect higher prices but excellent infrastructure.</p>\n<p><strong>Saburtalo:</strong> More affordable option with good transport links. Popular with young professionals and students.</p>\n<p><strong>Old Town:</strong> Historic charm but can be noisy. Perfect if you want to be in the heart of the action.</p>\n<p><strong>Vera:</strong> Quiet residential area with a mix of old and new buildings. Good balance of price and location.</p>\n\n<h3>What to Expect</h3>\n<ul>\n<li>Most rentals are unfurnished or partially furnished</li>\n<li>Utilities are usually separate (around 100-200 GEL per month)</li>\n<li>First month + deposit (usually 1-2 months) required upfront</li>\n<li>Many landlords prefer cash payments</li>\n</ul>\n\n<h3>Red Flags to Avoid</h3>\n<p>Be wary of apartments without proper heating, unreliable hot water, or in buildings with elevator issues. Always visit in person and ask about utility costs.</p>\n\n<h3>My Recommendation</h3>\n<p>Take your time, visit multiple places, and don't be afraid to negotiate. The Georgian rental market is quite flexible, and landlords are often willing to work with good tenants.</p>",author:"Stew Norriss",date:"2024-10-10",readTime:"8 min read",category:"Living",published:!0,hasImages:!0,hasVideo:!1,featuredImage:"https://images.unsplash.com/photo-1560448204-e02f11c3d0e2?w=800&h=400&fit=crop&crop=center",tags:["apartment-hunting","housing","expat-tips","neighborhoods"],createdAt:"2024-10-10T11:00:00Z",updatedAt:"2024-10-10T11:00:00Z"},{id:6,title:"Georgian Wine Culture: A Beginner's Guide",excerpt:"Discovering the world's oldest wine tradition. From qvevri to chacha, here's everything you need to know...",content:"<h2>8,000 Years of Winemaking Tradition</h2>\n<p>Georgia is considered the birthplace of wine, with archaeological evidence of winemaking dating back 8,000 years. As someone who's always enjoyed wine, diving into Georgian wine culture has been absolutely fascinating.</p>\n\n<h3>The Qvevri Method</h3>\n<p>Traditional Georgian wine is made in large clay vessels called qvevri, which are buried underground. This ancient method creates wines with unique flavors and characteristics you won't find anywhere else in the world.</p>\n\n<h3>Must-Try Georgian Wines</h3>\n<p><strong>Saperavi:</strong> A bold red wine that's Georgia's signature grape. Rich, full-bodied, and perfect with Georgian cuisine.</p>\n<p><strong>Rkatsiteli:</strong> A versatile white wine that can be dry or sweet. Great for beginners to Georgian wine.</p>\n<p><strong>Mtsvane:</strong> A crisp white wine with floral notes. Perfect for summer evenings.</p>\n\n<h3>Wine Regions to Visit</h3>\n<p><strong>Kakheti:</strong> The main wine region, home to most of Georgia's vineyards. Perfect for day trips from Tbilisi.</p>\n<p><strong>Kartli:</strong> Closer to Tbilisi, with some excellent smaller wineries.</p>\n\n<h3>Chacha: Georgia's National Spirit</h3>\n<p>Made from grape pomace, chacha is Georgia's answer to grappa. It's strong (40-70% alcohol) and often homemade. Approach with caution!</p>\n\n<h3>Wine Etiquette</h3>\n<p>Georgians take their wine seriously. When invited to a supra (traditional feast), expect elaborate toasts and lots of wine. It's considered rude to refuse, but you can always just sip.</p>",author:"Stew Norriss",date:"2024-10-08",readTime:"6 min read",category:"Food & Drink",published:!0,hasImages:!0,hasVideo:!1,featuredImage:"https://images.unsplash.com/photo-1506377247377-2a5b3b417ebb?w=800&h=400&fit=crop&crop=center",tags:["wine","culture","qvevri","chacha","kakheti"],createdAt:"2024-10-08T15:00:00Z",updatedAt:"2024-10-08T15:00:00Z"},{id:7,title:"Public Transport in Tbilisi: Metro, Buses, and More",excerpt:"Getting around the city like a local. Everything you need to know about Tbilisi's public transport system...",content:"<h2>Navigating Tbilisi's Transport Network</h2>\n<p>Tbilisi has a surprisingly efficient public transport system once you understand how it works. Here's your complete guide to getting around the city without a car.</p>\n\n<h3>The Metro System</h3>\n<p>Tbilisi's metro has two lines and is incredibly affordable (just 1 GEL per ride). The stations are beautifully decorated Soviet-era architecture worth seeing in their own right. Key stations for tourists:</p>\n<ul>\n<li><strong>Rustaveli:</strong> City center, near many attractions</li>\n<li><strong>Avlabari:</strong> Close to Old Town and Narikala Fortress</li>\n<li><strong>Station Square:</strong> Main railway station and bus terminal</li>\n</ul>\n\n<h3>City Buses</h3>\n<p>The bus network covers the entire city. Most buses are modern and air-conditioned. Use the same transport card as the metro (1 GEL per ride). Google Maps works well for bus routes and timing.</p>\n\n<h3>Marshrutkas (Minibuses)</h3>\n<p>These Soviet-era minibuses are an adventure in themselves. They're cheap (0.80 GEL) but can be crowded and confusing for newcomers. Great for reaching areas not covered by regular buses.</p>\n\n<h3>The Transport Card</h3>\n<p>Get a MetroMoney card from any metro station. You can load money and use it for metro, buses, and even some cable cars. Much more convenient than carrying exact change.</p>\n\n<h3>Taxis and Ride-Sharing</h3>\n<p>Bolt is the most popular ride-sharing app. Taxis are affordable, but always use the app to avoid overcharging. A typical ride across the city costs 5-15 GEL.</p>\n\n<h3>Pro Tips</h3>\n<ul>\n<li>Download the Tbilisi Transport app for real-time bus tracking</li>\n<li>Metro runs until midnight on weekdays, 1 AM on weekends</li>\n<li>Rush hours are 8-10 AM and 6-8 PM - expect crowds</li>\n<li>Keep your transport card handy - you'll use it more than you think</li>\n</ul>",author:"Stew Norriss",date:"2024-10-05",readTime:"7 min read",category:"Living",published:!0,hasImages:!1,hasVideo:!0,featuredImage:"https://images.unsplash.com/photo-1544620347-c4fd4a3d5957?w=800&h=400&fit=crop&crop=center",tags:["transport","metro","buses","getting-around","practical-tips"],createdAt:"2024-10-05T12:00:00Z",updatedAt:"2024-10-05T12:00:00Z"},{id:8,title:"Weekend Trip to Mtskheta: Georgia's Ancient Capital",excerpt:"A day trip to one of Georgia's most important historical sites. UNESCO World Heritage sites and incredible history...",content:"<h2>Stepping Back 1,500 Years</h2>\n<p>Just 20 kilometers from Tbilisi lies Mtskheta, the ancient capital of Georgia and one of the country's most important historical and religious sites. This UNESCO World Heritage site is perfect for a day trip.</p>\n\n<h3>Getting There</h3>\n<p>Take a marshrutka from Didube Bus Station (2 GEL, 30 minutes) or drive/take a taxi (about 45 minutes depending on traffic). I recommend going early in the morning to avoid crowds and heat.</p>\n\n<h3>Svetitskhoveli Cathedral</h3>\n<p>This 11th-century cathedral is said to house Christ's robe and is one of the most sacred places in Georgia. The architecture is breathtaking, and the religious significance is palpable. Entry is free, but dress modestly.</p>\n\n<h3>Jvari Monastery</h3>\n<p>Perched on a hilltop overlooking the confluence of two rivers, this 6th-century monastery offers stunning views of Mtskheta and the surrounding valley. The short hike up is worth it for the panoramic views.</p>\n\n<h3>Local Food</h3>\n<p>Try the local specialty - Mtskheta khachapuri, which has a slightly different preparation than Tbilisi versions. There are several good restaurants near the cathedral with traditional Georgian cuisine.</p>\n\n<h3>What to Bring</h3>\n<ul>\n<li>Comfortable walking shoes</li>\n<li>Sun protection (limited shade)</li>\n<li>Camera (the views are incredible)</li>\n<li>Modest clothing for religious sites</li>\n<li>Water bottle</li>\n</ul>\n\n<h3>My Experience</h3>\n<p>Walking through Mtskheta felt like traveling through time. The combination of ancient architecture, religious significance, and natural beauty makes it one of my favorite places in Georgia. It's a perfect introduction to Georgian history and culture.</p>",author:"Stew Norriss",date:"2024-10-03",readTime:"5 min read",category:"Travel",published:!0,hasImages:!0,hasVideo:!1,featuredImage:"https://images.unsplash.com/photo-1578662996442-48f60103fc96?w=800&h=400&fit=crop&crop=center",tags:["mtskheta","day-trip","history","unesco","svetitskhoveli"],createdAt:"2024-10-03T14:00:00Z",updatedAt:"2024-10-03T14:00:00Z"}];function BlogProvider(e){let{children:t}=e,[i,l]=(0,n.useState)([]);(0,n.useEffect)(()=>{{let e=localStorage.getItem(o);if(e)try{l(JSON.parse(e))}catch(e){console.error("Error loading posts from localStorage:",e),l(s)}else l(s)}},[]),(0,n.useEffect)(()=>{i.length>0&&localStorage.setItem(o,JSON.stringify(i))},[i]);let calculateReadTime=e=>{let t=e.replace(/<[^>]*>/g,"").split(/\s+/).length;return"".concat(Math.ceil(t/200)," min read")};return(0,a.jsx)(r.Provider,{value:{posts:i,createPost:e=>{let t=new Date().toISOString(),i={...e,id:Date.now(),date:new Date().toISOString().split("T")[0],readTime:calculateReadTime(e.content),createdAt:t,updatedAt:t};l(e=>[i,...e])},updatePost:(e,t)=>{l(i=>i.map(i=>i.id===e?{...i,...t,readTime:t.content?calculateReadTime(t.content):i.readTime,updatedAt:new Date().toISOString()}:i))},deletePost:e=>{l(t=>t.filter(t=>t.id!==e))},togglePublished:e=>{l(t=>t.map(t=>t.id===e?{...t,published:!t.published,updatedAt:new Date().toISOString()}:t))},getPost:e=>i.find(t=>t.id===e),getPublishedPosts:()=>i.filter(e=>e.published).sort((e,t)=>new Date(t.date).getTime()-new Date(e.date).getTime()),getDraftPosts:()=>i.filter(e=>!e.published).sort((e,t)=>new Date(t.updatedAt).getTime()-new Date(e.updatedAt).getTime()),searchPosts:e=>{let t=e.toLowerCase();return i.filter(e=>e.title.toLowerCase().includes(t)||e.excerpt.toLowerCase().includes(t)||e.content.toLowerCase().includes(t)||e.category.toLowerCase().includes(t)||e.tags&&e.tags.some(e=>e.toLowerCase().includes(t)))},getPostsByCategory:e=>"all"===e?i:i.filter(t=>t.category===e)},children:t})}function useBlog(){let e=(0,n.useContext)(r);if(void 0===e)throw Error("useBlog must be used within a BlogProvider");return e}}}]);